@app.get('/api/telemetry')
def get_telemetry_data():
    """Aggregates local database logs and code architecture blueprints."""
    response_data = {'blueprint': {}, 'metrics': {'Architecture': 0.0, 'Backend Logic': 0.0, 'Security': 0.0, 'Databases': 0.0, 'Scalability': 0.0}, 'weaknesses': []}
    if os.path.exists(BLUEPRINT_PATH):
        try:
            with open(BLUEPRINT_PATH, 'r', encoding='utf-8') as f:
                response_data['blueprint'] = json.load(f)
        except Exception:
            pass
    if os.path.exists(DB_PATH):
        try:
            conn = sqlite3.connect(DB_PATH)
            cursor = conn.cursor()
            cursor.execute('\n                SELECT \n                    AVG(architecture_score), AVG(backend_logic_score), \n                    AVG(security_score), AVG(database_score), AVG(scalability_score) \n                FROM session_metrics\n            ')
            row = cursor.fetchone()
            if row and row[0] is not None:
                response_data['metrics'] = {'Architecture': round(row[0], 1), 'Backend Logic': round(row[1], 1), 'Security': round(row[2], 1), 'Databases': round(row[3], 1), 'Scalability': round(row[4], 1)}
            cursor.execute('SELECT DISTINCT topic_tag FROM concept_weaknesses')
            response_data['weaknesses'] = [tag[0] for tag in cursor.fetchall()]
            conn.close()
        except Exception:
            pass
    return response_data

