def select_and_scan_repository(payload: RepoSelectPayload):
    target_path = payload.repo_path.strip()
    if not os.path.exists(target_path):
        raise HTTPException(status_code=400, detail=f"Target path layout not found on this system: '{target_path}'")
    try:
        print(f'📁 Initializing deep AST crawl on target workspace: {target_path}')
        parsed_list = crawl_repository(target_path)
        blueprint_data = {'repo_path': target_path, 'files': {os.path.basename(item.get('file_path', 'module')): item for item in parsed_list if isinstance(item, dict)} if parsed_list and isinstance(parsed_list[0], dict) else {}, 'raw_ast_pool': parsed_list}
