def router_node(state: AgentState) -> Dict[str, Any]:
    print('🤖 Agent Node [Router]: Analyzing context and querying vector store...')
    if state['query'] == 'INITIALIZE_INTERVIEW_SESSION':
        return {'retrieved_code_vectors': [], 'steps_taken': state.get('steps_taken', []) + ['live_routed']}
    search_query = state['query']
    if state.get('messages') and len(state['messages']) > 1:
        print('   ↳ 🧠 Context detected. Condensing shorthand query via Gemini...')
        chat_history_context = ''
        for msg in state['messages'][:-1]:
            chat_history_context += f"{msg['role']}: {msg['content']}\n"
        condensation_prompt = f"Given the following conversation history and a new shorthand follow-up question, rewrite the new question into a standalone, descriptive search query focused on resolving the intended codebase target files or symbols.\n\nConversation History:\n{chat_history_context}\nNew Follow-up Question: {state['query']}\n\nOutput ONLY the optimized search string. Do not include introductory text."
        try:
            condensation_response = ai_client.models.generate_content(model='gemini-2.5-flash', contents=condensation_prompt)
            optimized_query = condensation_response.text.strip()
            if optimized_query:
                search_query = optimized_query
                print(f"   ↳ Optimized Search Vector: '{search_query}'")
        except Exception as e:
            print(f'   ↳ ⚠️ Query condensation skipped due to error: {e}')
    chroma_client = chromadb.PersistentClient(path='./chroma_db_data')
    collection = chroma_client.get_collection(name='repository_methods')
    results = collection.query(query_texts=[search_query], n_results=2)
    retrieved_docs = []
    if results and results['documents'] and results['documents'][0]:
        for doc, metadata in zip(results['documents'][0], results['metadatas'][0]):
            retrieved_docs.append({'file': metadata.get('file_path', 'unknown'), 'scope': metadata.get('scope', 'unknown'), 'symbol_name': metadata.get('symbol_name', 'unknown'), 'content': doc})
            print(f"   ↳ Extracted relevant {metadata.get('scope')}: '{metadata.get('symbol_name')}' from {metadata.get('file_path')}")
    if not retrieved_docs:
        print('   ↳ ⚠️ Warning: No relevant code vectors found for this query.')
    return {'retrieved_code_vectors': retrieved_docs, 'steps_taken': state.get('steps_taken', []) + ['live_routed']}

