    for vec in state['retrieved_code_vectors']:
        code_context += f"\n--- FILE: {vec['file']} ({vec['scope']}: {vec['symbol_name']}) ---\n{vec['content']}\n"
    chat_history_context = ''
    for msg in state.get('messages', []):
        chat_history_context += f"👤 {msg['role'].capitalize()}: {msg['content']}\n"
    system_instruction = 'You are an expert technical AI assistant linked directly to a local codebase. Your job is to provide clean, technical, and accurate code summaries or answers using the retrieved code context assets and conversation history. Always format code references within proper markdown ticks.'
    user_prompt = ''
    if chat_history_context:
        user_prompt += f'Prior Conversation History:\n{chat_history_context}\n'
    user_prompt += f'Code Context Assets for Current Turn:\n{code_context}\n\n'
