def post_evaluation_router(state: AgentState) -> str:
    """
    Determines where to route after an evaluation node finishes processing.
    """
    if state.get('session_mode') == 'interview':
        if state.get('current_question_index', 1) <= 5:
            return 'generate_interview_turn'
        else:
            evaluation_scores = state.get('evaluation_scores', [])
            category_scores = {'architecture': 50.0, 'backend_logic': 50.0, 'security': 50.0, 'databases': 50.0, 'scalability': 50.0}
            weaknesses = []
            count = 0
            for entry in evaluation_scores:
                payload = entry.get('json_payload') or {}
                if payload:
                    count += 1
                    category_scores['architecture'] += payload.get('architecture_percentage', 50)
                    category_scores['backend_logic'] += payload.get('backend_logic_percentage', 50)
                    category_scores['security'] += payload.get('security_percentage', 50)
                    category_scores['databases'] += payload.get('databases_percentage', 50)
                    category_scores['scalability'] += payload.get('scalability_percentage', 50)
                    weaknesses.extend(payload.get('flagged_weaknesses', []))
            if count > 0:
                category_scores = {k: v / count for k, v in category_scores.items()}
            weaknesses = [w.strip().lower() for w in set(weaknesses) if w and isinstance(w, str)]
            metadata = {'session_mode': state.get('session_mode', 'interview'), 'difficulty': state.get('difficulty', 'medium'), 'interviewer_persona': state.get('interviewer_persona', 'architect')}
            try:
                log_completed_session(metadata, category_scores, weaknesses)
            except Exception as log_error:
                print(f'  ⚠️ Failed to persist completed session: {log_error}')
            return 'end'
    if state.get('review_feedback'):
        return 'write_docs'
    return 'end'

def crawl_repository(repo_path: str) -> list:
    """
    Sifts through a directory recursively, finds all Python files,
    and runs them through our AST parser.
    """
    all_parsed_data = []
    if not os.path.exists(repo_path):
        print(f"Error: The path '{repo_path}' does not exist.")
        return all_parsed_data
    for root, dirs, files in os.walk(repo_path):
        dirs[:] = [d for d in dirs if not d.startswith('.') and d not in ['venv', '__pycache__', 'env']]
        for file in files:
            if file.endswith('.py'):
                full_file_path = os.path.join(root, file)
                print(f'Scanning: {full_file_path}')
                file_data = parse_python_file(full_file_path)
                module_rel = os.path.relpath(full_file_path, repo_path).replace(os.sep, '/')
                if file_data:
                    if isinstance(file_data, dict):
                        file_data.setdefault('file_path', full_file_path)
                        file_data.setdefault('module', module_rel)
                        all_parsed_data.append(file_data)
                    else:
                        all_parsed_data.append({'file_path': full_file_path, 'module': module_rel, 'raw': file_data})
    return all_parsed_data

def parse_python_file(file_path: str):
    """
    This function will read a Python file and turn its structure into data.
    """
    with open(file_path, 'r', encoding='utf-8') as source_file:
        source_code = source_file.read()
    try:
        tree = ast.parse(source_code)
    except SyntaxError as e:
        print(f'Skipping {file_path} due to a syntax error: {e}')
        return None
    file_metadata = {'file_path': file_path, 'classes': [], 'standalone_functions': []}
    for node in tree.body:
        if isinstance(node, ast.ClassDef):
            class_info = {'name': node.name, 'docstring': ast.get_docstring(node), 'methods': []}
            for sub_node in node.body:
                if isinstance(sub_node, ast.FunctionDef):
                    method_info = {'name': sub_node.name, 'args': [arg.arg for arg in sub_node.args.args], 'docstring': ast.get_docstring(sub_node), 'source_code': ast.unparse(sub_node)}
                    class_info['methods'].append(method_info)
            file_metadata['classes'].append(class_info)
        elif isinstance(node, ast.FunctionDef):
            func_info = {'name': node.name, 'args': [arg.arg for arg in node.args.args], 'docstring': ast.get_docstring(node), 'source_code': ast.unparse(node)}
            file_metadata['standalone_functions'].append(func_info)
    return file_metadata

