def parse_js_ts_file(file_path: str, content: str) -> Dict[str, Any]:
    """Extracts symbols, exports, and imports from JavaScript/TypeScript files using optimized regex scanning."""
    meta = {'language': 'javascript/typescript', 'imports': [], 'classes': {}, 'standalone_functions': []}
    es6_imports = re.findall('(?:import|from)\\s+[\'\\"]([^\'\\"]+)[\'\\"]', content)
    commonjs_imports = re.findall('require\\s*\\(\\s*[\'\\"]([^\'\\"]+)[\'\\"]\\s*\\)', content)
    for imp in set(es6_imports + commonjs_imports):
        if not imp.startswith('.'):
            meta['imports'].append(imp)
    classes = re.findall('class\\s+(\\w+)(?:\\s+extends\\s+(\\w+))?', content)
    for cls, base in classes:
        meta['classes'][cls] = {'methods': [], 'base_classes': [base] if base else []}
    found_functions = re.findall('function\\s+(\\w+)\\s*\\(', content)
    found_arrow_funcs = re.findall('(?:const|let|var)\\s+(\\w+)\\s*=\\s*(?:\\([^)]*\\)|_\\w*)\\s*=>', content)
    for func in set(found_functions + found_arrow_funcs):
        meta['standalone_functions'].append(func)
    return meta

def generate_repository_graph(root_dir: str) -> Dict[str, Any]:
    """Crawl the workspace to compile a high-level Python & JS/TS dependency and structural graph map."""
    repo_graph = {'project_root': os.path.basename(os.path.abspath(root_dir)), 'manifest_dependencies': {}, 'directory_tree': {}, 'modules': {}}
    package_json_path = os.path.join(root_dir, 'package.json')
    if os.path.exists(package_json_path):
        try:
            with open(package_json_path, 'r', encoding='utf-8') as f:
                pkg_data = json.load(f)
                repo_graph['manifest_dependencies'] = {**pkg_data.get('dependencies', {}), **pkg_data.get('devDependencies', {})}
        except Exception as e:
            repo_graph['manifest_dependencies'] = {'error': f'Failed to parse package.json: {e}'}
    supported_extensions = ('.py', '.js', '.ts', '.jsx', '.tsx')
    for root, dirs, files in os.walk(root_dir):
        if any((ignored in root for ignored in ['.git', '__pycache__', 'node_modules', 'venv', '.venv', 'chroma_db', 'storage', 'scorecards', 'dist', 'build', '.next'])):
            continue
        rel_path = os.path.relpath(root, root_dir)
        dir_key = 'root' if rel_path == '.' else rel_path
        tracked_files = [f for f in files if f.endswith(supported_extensions)]
        if tracked_files:
            repo_graph['directory_tree'][dir_key] = tracked_files
        for file in files:
            if file.endswith(supported_extensions):
                full_path = os.path.join(root, file)
                module_key = os.path.relpath(full_path, root_dir).replace(os.sep, '/')
                try:
                    with open(full_path, 'r', encoding='utf-8') as f:
                        file_content = f.read()
                    if file.endswith('.py'):
                        tree = ast.parse(file_content, filename=file)
                        analyzer = CodebaseGraphAnalyzer(module_key)
                        analyzer.visit(tree)
                        repo_graph['modules'][module_key] = analyzer.meta
                    else:
                        repo_graph['modules'][module_key] = parse_js_ts_file(module_key, file_content)
                except Exception as e:
                    repo_graph['modules'][module_key] = {'error': f'Failed to parse source tree elements: {e}'}
    output_path = os.path.join(root_dir, 'repo_blueprint.json')
    with open(output_path, 'w', encoding='utf-8') as out:
        json.dump(repo_graph, out, indent=4)
    print(f"🎯 [Repository Graph]: Blueprint map successfully compiled to '{output_path}'.")
    return repo_graph

def _array_keys(value):
    for i in range(len(value)):
        yield i

def _object_keys(value):
    for key in value:
        yield key

def _relate(known, input, value):
    if _is_string(value) or _is_array(value) or _is_object(value):
        try:
            return known.value[known.key.index(value)]
        except:
            return _index(known, input, value)
    return value

def _resolver(input, lazy, parsed):

    def resolver(output):
        keys = _array_keys(output) if _is_array(output) else _object_keys(output) if _is_object(output) else []
        for key in keys:
            value = output[key]
            if isinstance(value, _String):
                tmp = input[int(value.value)]
                output[key] = tmp
                if (_is_array(tmp) or _is_object(tmp)) and tmp not in parsed:
                    parsed.append(tmp)
                    lazy.append([output, key])
        return output
    return resolver

def _transform(known, input, value):
    if _is_array(value):
        output = []
        for val in value:
            output.append(_relate(known, input, val))
        return output
    if _is_object(value):
        obj = {}
        for key in value:
            obj[key] = _relate(known, input, value[key])
        return obj
    return value

def _wrap(value):
    if _is_string(value):
        return _String(value)
    if _is_array(value):
        i = 0
        for val in value:
            value[i] = _wrap(val)
            i += 1
    elif _is_object(value):
        for key in value:
            value[key] = _wrap(value[key])
    return value

def stringify(value, *args, **kwargs):
    known = _Known()
    input = []
    output = []
    i = int(_index(known, input, value))
    while i < len(input):
        output.append(_transform(known, input, input[i]))
        i += 1
    return _json.dumps(output, *args, **kwargs)

