def __init__(self, file_path: str):
    self.file_path = file_path
    self.meta = {'language': 'python', 'imports': [], 'classes': {}, 'standalone_functions': []}
    self.current_class = None

def visit_Import(self, node):
    for alias in node.names:
        self.meta['imports'].append(alias.name)
    self.generic_visit(node)

def visit_ImportFrom(self, node):
    if node.module:
        self.meta['imports'].append(node.module)
    self.generic_visit(node)

def visit_ClassDef(self, node):
    class_name = node.name
    self.meta['classes'][class_name] = {'methods': [], 'base_classes': [ast.unparse(b) for b in node.bases]}
    self.current_class = class_name
    self.generic_visit(node)
    self.current_class = None

def visit_FunctionDef(self, node):
    func_name = node.name
    if self.current_class:
        self.meta['classes'][self.current_class]['methods'].append(func_name)
    else:
        self.meta['standalone_functions'].append(func_name)
    self.generic_visit(node)

